#include "app/Controller.h"
#include "hmi/Transport.h"
#include "HostPorts.h"
#include <functional>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <deque>
#include <cstring>
#include <limits>
#include <map>
using namespace conmt;
#define REQUIRE(x) do { if(!(x)) throw std::runtime_error(std::string(__FILE__)+":"+std::to_string(__LINE__)+" "+#x); } while(0)
#define PASS(x) REQUIRE((x)==Status::Ok)
struct Rig {
    host::MemoryStorage io; Journal j; Repository r;
    host::FakeClock time; host::RecordedSensor sensor; host::Devices device;
    Controller app;
    Rig():j(io),r(j),app(r,time,sensor,device){PASS(app.boot());}
    void identity(){PASS(app.setField("operator","OP-1"));PASS(app.setField("project","ConMT"));PASS(app.setField("date","2026-11-16"));}
    void baseline(){identity();PASS(app.newBaseline());PASS(app.setField("name","B"));PASS(app.setField("target","30"));PASS(app.editRow(2,"day","1"));PASS(app.editRow(3,"day","2"));for(int i=1;i<=3;++i)PASS(app.editRow(i,"temp","20"));PASS(app.editRow(2,"fc","10"));PASS(app.editRow(3,"fc","20"));PASS(app.generate());PASS(app.saveBaseline());}
};
class Wire:public UartPort{
public:
    std::deque<uint8_t> rx;std::string tx;uint16_t credit=64;
    int read() override{if(rx.empty())return -1;int b=rx.front();rx.pop_front();return b;}
    uint16_t writable() override{return credit;}
    uint16_t write(const uint8_t* p,uint16_t n) override{tx.append(reinterpret_cast<const char*>(p),n);return n;}
    void input(const std::string& s){for(unsigned char b:s)rx.push_back(b);}
};
static void drain(Transport& p,uint32_t now=0){for(unsigned n=0;n<1500;++n)p.poll(now);}
static std::string request(Rig& r,uint32_t seq,const std::string& body){std::ostringstream o;o<<"CM1|"<<r.app.bootToken()<<'|'<<seq<<'|'<<unsigned(r.app.page())<<'|'<<r.app.view()<<'|'<<body<<'\n';return o.str();}
static unsigned failures=0,cases=0;
static void test(const char* name,const std::function<void()>& fn){++cases;try{fn();std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failures;std::cerr<<"FAIL "<<name<<" : "<<e.what()<<'\n';}}
int main(){
    test("A01 newest baseline first",[]{Rig t;t.baseline();PASS(t.app.saveBaseline());uint32_t id;PASS(t.app.baselineAt(0,id));REQUIRE(id==2);});
    test("A02 selection restored on boot",[]{Rig t;t.baseline();PASS(t.app.saveBaseline());PASS(t.app.select(1));Controller app(t.r,t.time,t.sensor,t.device);PASS(app.boot());REQUIRE(app.selectedId()==1);});
    test("A03 JavaScript fixed-point ties",[]{char b[32];formatReal(b,sizeof(b),2.5,0);REQUIRE(!strcmp(b,"3"));formatReal(b,sizeof(b),3.125,2);REQUIRE(!strcmp(b,"3.13"));formatReal(b,sizeof(b),2.675,2);REQUIRE(!strcmp(b,"2.67"));});
    test("A04 gap covers complete outage",[]{Rig t;t.baseline();PASS(t.app.start());t.sensor.frame.validMask=0;t.time.advance(1000);REQUIRE(t.app.tick()==Status::NoSensor);t.time.advance(60000);t.app.tick();t.sensor.frame.validMask=7;t.time.advance(1000);t.app.tick();uint64_t end;PASS(t.r.time(Key(Kind::Session,1,Field::GapEnd),end));REQUIRE(end>=t.time.value.wallMs);});
    test("A05 transient sensor status clears to unresolved gap",[]{Rig t;t.baseline();PASS(t.app.start());t.sensor.frame.validMask=0;t.time.advance(1000);t.app.tick();t.sensor.frame.validMask=7;t.time.advance(1000);t.app.tick();REQUIRE(t.app.status()==Status::Gap);});
    test("A06 corrupt brightness is not narrowed before checking",[]{Rig t;PASS(t.j.begin());PASS(t.r.putInteger(Key(Kind::Settings,0,Field::Brightness),256));PASS(t.j.commit());Controller app(t.r,t.time,t.sensor,t.device);REQUIRE(app.boot()==Status::Corrupt);});
    test("A07 missing sensor initializes average output",[]{class Bad:public SensorPort{public:void poll(uint32_t) override{}Status latest(SensorFrame&) override{return Status::IoError;}}bad;host::MemoryStorage m;Journal j(m);Repository r(j);host::FakeClock c;host::Devices d;Controller app(r,c,bad,d);PASS(app.boot());Average a{99,99,7};REQUIRE(app.getAverage(a)==Status::IoError);REQUIRE(a.mask==0&&a.raw==0);});
    test("A08 input frame counts LF in 192 byte limit",[]{Parser p;Frame f;std::string s="CM1|1|1|1|1|X|";s.append(192-s.size(),'A');Status st=Status::Busy;for(unsigned char b:s)st=p.feed(b,0,f);st=p.feed('\n',0,f);REQUIRE(st==Status::Invalid);});
    test("A09 surplus command arguments rejected",[]{Rig t;Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);w.tx.clear();w.input(request(t,1,"FIELD_SET|operator|CHANGED|EXTRA"));drain(p);char b[33];REQUIRE(t.r.text(Key(Kind::User,0,Field::Operator),b,33)==Status::Missing);REQUIRE(w.tx.find("pInit.vStatus.val=2")!=std::string::npos);});
    test("A10 status refresh does not arm command retry",[]{Rig t;Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);w.tx.clear();drain(p,1000);REQUIRE(w.tx.find("pInit.vBusy.val=1")==std::string::npos);});
    test("A11 page ready preserves command ACK",[]{Rig t;t.identity();Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);w.tx.clear();w.input(request(t,7,"USER_SAVE"));p.poll(1);w.input("CM1|0|0|2|0|PAGE_READY|2\n");drain(p,1);REQUIRE(w.tx.find("pInit.vAck.val=7")!=std::string::npos);});
    test("A12 panel reset cannot reuse old operation IDs",[]{Rig t;Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);w.input(request(t,1,"FIELD_SET|operator|BEFORE"));drain(p);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);w.input(request(t,1,"FIELD_SET|operator|AFTER"));drain(p);char text[33];PASS(t.r.text(Key(Kind::User,0,Field::Operator),text,33));REQUIRE(!strcmp(text,"AFTER"));});
    test("A13 render restarts before publishing new generation",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.setField("name","OLD"));Wire w;Transport p(t.app,w);w.input("CM1|0|0|4|0|PAGE_READY|2\n");for(unsigned i=0;i<1000&&w.tx.find("tName.txt=\"OLD\"")==std::string::npos;++i)p.poll(0);PASS(t.app.setField("name","NEW"));drain(p);REQUIRE(w.tx.find("tName.txt=\"NEW\"")!=std::string::npos);});
    test("A14 invalid clock is not displayed as midnight",[]{Rig t;t.time.value.valid=false;Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);REQUIRE(w.tx.find("tClock.txt=\"--\"")!=std::string::npos);});
    test("A15 model with nonfinite coefficients rejected by codec",[]{Rig t;Fit f;f.valid=true;f.a=std::numeric_limits<Real>::infinity();f.b=1;f.r2=1;f.n=2;PASS(t.j.begin());REQUIRE(t.r.putModel(Kind::Draft,1,f)==Status::Invalid);t.j.abort();});
    test("A16 finite channels cannot create infinite average",[]{SensorFrame f;f.validMask=7;f.channel[0]=f.channel[1]=f.channel[2]=std::numeric_limits<Real>::max();Average a;Status s=average(f,0,5000,a);REQUIRE(s!=Status::Ok||finite(a.raw));});
    test("A17 RTC regression creates ordered gap bounds",[]{Rig t;t.baseline();PASS(t.app.start());t.time.value.wallMs-=10000;t.time.value.monoMs+=1000;t.app.tick();uint64_t start,end;PASS(t.r.time(Key(Kind::Session,1,Field::GapStart),start));PASS(t.r.time(Key(Kind::Session,1,Field::GapEnd),end));REQUIRE(start<=end);});
    test("A18 recovery preserves earliest unresolved gap",[]{Rig t;t.baseline();PASS(t.app.start());t.time.advance(1000);t.sensor.frame.validMask=0;t.app.tick();uint64_t initial;PASS(t.r.time(Key(Kind::Session,1,Field::GapStart),initial));t.time.advance(10000);Controller c(t.r,t.time,t.sensor,t.device);PASS(c.boot());uint64_t restored;PASS(t.r.time(Key(Kind::Session,1,Field::GapStart),restored));REQUIRE(restored==initial);});

    test("A19 preview keeps its sensor snapshot",[]{Rig t;t.identity();PASS(t.app.dispatch("USER_SAVE"));PASS(t.app.dispatch("NAV","15"));PASS(t.app.dispatch("SETTINGS_SET","autoSave","1"));t.baseline();PASS(t.app.start());PASS(t.app.prepareResult());for(unsigned i=0;i<3;++i)t.sensor.frame.channel[i]=30;for(unsigned i=0;i<301;++i){t.time.advance(1000);PASS(t.app.tick());}PASS(t.app.saveResult());uint8_t b[53];uint16_t n=53;PASS(t.j.get(Key(Kind::Result,1,Field::Sensors),b,n));REQUIRE(getReal(b+12)==20);});
    test("A20 hardware setting rolls back on storage failure",[]{Rig t;t.identity();PASS(t.app.dispatch("USER_SAVE"));PASS(t.app.dispatch("NAV","15"));REQUIRE(t.device.light==80);t.io.full=true;REQUIRE(t.app.dispatch("SETTINGS_SET","brightness","50")==Status::Full);REQUIRE(t.device.light==80&&t.app.settings().brightness==80);});
    test("A21 sensor capture does not wrap revision",[]{Rig t;t.baseline();PASS(t.app.openBaseline(1));Row row;PASS(t.r.row(Kind::Draft,t.app.draftId(),1,row));row.revision=UINT32_MAX;PASS(t.j.begin());PASS(t.r.putRow(Kind::Draft,t.app.draftId(),row));PASS(t.j.commit());REQUIRE(t.app.captureRow(1)==Status::Capacity);});
    test("A22 no future observation in production checkpoint",[]{Rig t;t.baseline();PASS(t.app.start());t.time.advance(1000);t.sensor.poll(t.time.value.monoMs);PASS(t.app.addCheckpoint(0));REQUIRE(t.app.editCheckpoint(2,"date","2199-12-30")==Status::Invalid);});
    test("A23 result codec validates all numerical fields",[]{Rig t;uint8_t b[73]={0};put64(b+24,0x7ff0000000000000ULL);PASS(t.j.begin());PASS(t.j.put(Key(Kind::Result,1,Field::Result),b,73));PASS(t.j.commit());Result r;REQUIRE(t.app.readResult(Kind::Result,1,r)==Status::Corrupt);});
    test("A24 unknown row flags rejected",[]{Rig t;uint8_t b[37]={0};put32(b,1);b[36]=129;PASS(t.j.begin());PASS(t.j.put(Key(Kind::Draft,1,Field::Row,1),b,37));PASS(t.j.commit());Row r;REQUIRE(t.r.row(Kind::Draft,1,1,r)==Status::Corrupt);});
    test("A25 current sensor strip is one coherent frame",[]{Rig t;t.baseline();PASS(t.app.start());Wire w;Transport p(t.app,w);w.input("CM1|0|0|11|0|PAGE_READY|2\n");for(unsigned i=0;i<1000&&w.tx.find("tS1.txt=\"20.0\"")==std::string::npos;++i)p.poll(0);t.sensor.frame.channel[1]=30;t.sensor.frame.channel[2]=40;drain(p);REQUIRE(w.tx.find("tS2.txt=\"20.0\"")!=std::string::npos);REQUIRE(w.tx.find("tAvg.txt=\"20.0\"")!=std::string::npos);});
    test("A26 BACK is independent of stale data view",[]{Rig t;PASS(t.app.newBaseline());Wire w;Transport p(t.app,w);w.input("CM1|0|0|4|0|PAGE_READY|2\n");drain(p);uint32_t view=t.app.view();PASS(t.app.setField("name","new edit"));std::ostringstream req;req<<"CM1|"<<t.app.bootToken()<<"|5|4|"<<view<<"|NAV|BACK\n";w.input(req.str());drain(p);REQUIRE(t.app.page()==Page::Base);});
    test("A27 storage rescan recovers absent media",[]{Rig t;t.io.absent=true;REQUIRE(t.app.boot()==Status::Absent);t.io.absent=false;PASS(t.app.dispatch("STORAGE_RESCAN"));PASS(t.app.newBaseline());});
    test("A28 wrong-body duplicate is rejected",[]{Rig t;Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);w.input(request(t,1,"FIELD_SET|operator|ONE"));drain(p);w.tx.clear();w.input(request(t,1,"FIELD_SET|operator|TWO"));drain(p);char b[33];PASS(t.r.text(Key(Kind::User,0,Field::Operator),b,33));REQUIRE(!strcmp(b,"ONE"));REQUIRE(w.tx.find("pInit.vStatus.val=13")!=std::string::npos);});

    test("A29 day-zero slot occupancy follows source snapping",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(2,"timeH","0.3"));PASS(t.app.addRow(true));Row row;PASS(t.r.row(Kind::Draft,t.app.draftId(),4,row));REQUIRE(row.timeH==Real(1.5));});
    test("A30 UI row order follows day then elapsed time",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(1,"day","2"));PASS(t.app.editRow(1,"timeH","1"));PASS(t.app.editRow(2,"day","1"));PASS(t.app.editRow(2,"timeH","2"));Row row;PASS(t.app.rowAt(1,row));REQUIRE(row.day==1);});
    test("A31 interval edits preserve other HH MM SS fields",[]{Rig t;t.identity();PASS(t.app.dispatch("USER_SAVE"));PASS(t.app.dispatch("NAV","15"));PASS(t.app.dispatch("SETTINGS_SET","hour","2"));PASS(t.app.dispatch("SETTINGS_SET","minute","13"));PASS(t.app.dispatch("SETTINGS_SET","second","9"));REQUIRE(t.app.settings().intervalSeconds==7989);REQUIRE(t.app.dispatch("SETTINGS_SET","minute","60")==Status::Invalid);});
    test("A32 obsolete HMI contract rejected",[]{Rig t;Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|1\n");drain(p);w.input(request(t,1,"FIELD_SET|operator|WRONG_VERSION"));drain(p);char text[33];REQUIRE(t.r.text(Key(Kind::User,0,Field::Operator),text,33)==Status::Missing);});

    test("A33 lab temperature retains manually entered precision",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(1,"temp","36.55"));PASS(t.app.dispatch("NAV","5"));PASS(t.app.dispatch("NAV","6"));Wire w;Transport p(t.app,w);w.input("CM1|0|0|6|0|PAGE_READY|2\n");drain(p);REQUIRE(w.tx.find("tT0.txt=\"36.55\"")!=std::string::npos);});
    test("A34 lab crushing value retains manually entered precision",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(1,"fc","14.86333"));PASS(t.app.dispatch("NAV","5"));PASS(t.app.dispatch("NAV","6"));Wire w;Transport p(t.app,w);w.input("CM1|0|0|6|0|PAGE_READY|2\n");drain(p);REQUIRE(w.tx.find("tFc0.txt=\"14.86333\"")!=std::string::npos);});
    test("A35 fractional day is not changed by display",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(1,"day","1.25"));PASS(t.app.dispatch("NAV","5"));PASS(t.app.dispatch("NAV","6"));Wire w;Transport p(t.app,w);w.input("CM1|0|0|6|0|PAGE_READY|2\n");drain(p);REQUIRE(w.tx.find("tDay2.txt=\"1.25\"")!=std::string::npos);});
    test("A36 unsupported calendar age cannot overflow timestamp",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(3,"timeH","1e20"));PASS(t.app.dispatch("NAV","5"));PASS(t.app.dispatch("NAV","6"));Wire w;Transport p(t.app,w);w.input("CM1|0|0|6|0|PAGE_READY|2\n");drain(p);REQUIRE(w.tx.find("tTim2.txt=\"--\"")!=std::string::npos);});
    test("A37 fresh pre-start sample does not cause false clock fault",[]{Rig t;t.baseline();t.time.advance(1000);t.sensor.frame.sampledMonoMs=500;t.sensor.fresh=false;PASS(t.app.start());t.time.advance(1);PASS(t.app.tick());});

    test("C01 fill preserves entered data and is repeatable",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(1,"temp","36.55"));PASS(t.app.fillEarly());uint32_t max;PASS(t.r.integer(Key(Kind::Draft,t.app.draftId(),Field::MaxRow),max));REQUIRE(max==13);Row row;PASS(t.r.row(Kind::Draft,t.app.draftId(),1,row));REQUIRE(row.temp==Real(36.55));PASS(t.app.fillEarly());PASS(t.r.integer(Key(Kind::Draft,t.app.draftId(),Field::MaxRow),max));REQUIRE(max==13);});
    test("C02 add lab chooses first unused day and delete respects minimum",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(1,"day","1"));PASS(t.app.editRow(2,"day","2"));PASS(t.app.editRow(3,"day","4"));PASS(t.app.addRow(false));Row row;PASS(t.r.row(Kind::Draft,t.app.draftId(),4,row));REQUIRE(row.day==3);REQUIRE(t.app.deleteRow(4,false)==Status::ConfirmRequired);PASS(t.app.deleteRow(4,true));REQUIRE(t.app.deleteRow(1,true)==Status::Invalid);});
    test("C03 manual input survives baseline save and reopen",[]{Rig t;t.baseline();PASS(t.app.editRow(1,"temp","36.55"));PASS(t.app.generate());PASS(t.app.saveBaseline());PASS(t.app.openBaseline(2));char text[65];PASS(t.r.text(Key(Kind::Draft,t.app.draftId(),Field::TempInput,1),text,65));REQUIRE(!strcmp(text,"36.55"));});
    test("C04 settings controls preserve source step limits",[]{Rig t;t.identity();PASS(t.app.dispatch("USER_SAVE"));PASS(t.app.dispatch("NAV","15"));PASS(t.app.dispatch("SETTINGS_SET","hour","23"));PASS(t.app.dispatch("SETTINGS_STEP","hour","1"));REQUIRE(t.app.settings().intervalSeconds/3600==23);PASS(t.app.dispatch("SETTINGS_SET","brightness","100"));PASS(t.app.dispatch("SETTINGS_STEP","brightness","5"));REQUIRE(t.device.light==100);bool before=t.app.settings().autoSave;PASS(t.app.dispatch("SETTINGS_TOGGLE","autoSave"));REQUIRE(t.app.settings().autoSave!=before);});
    test("C05 raw and rounded maturity stay distinct",[]{Rig t;t.baseline();PASS(t.app.start());t.time.advance(86445000);t.sensor.poll(t.time.value.monoMs);PASS(t.app.addCheckpoint(1));Result raw;PASS(t.app.checkpointResult(Kind::Session,1,0,raw));PASS(t.app.prepareResult());Result summary;PASS(t.app.readResult(Kind::Session,1,summary));REQUIRE(fabs(raw.rawM-Real(960.5))<Real(.001));REQUIRE(summary.prediction.maturity==floor(summary.rawM+Real(.5)));REQUIRE(fabs(raw.prediction.fc-summary.prediction.fc)>Real(.001));});
    test("C06 missing sensor/clock cannot START or create a session",[]{Rig t;t.baseline();t.sensor.frame.validMask=0;REQUIRE(t.app.start()==Status::NoSensor&&t.app.sessionId()==0);t.sensor.frame.validMask=7;t.time.value.valid=false;REQUIRE(t.app.start()==Status::NoClock&&t.app.sessionId()==0);});

    test("A38 committed corruption is not silently truncated as a tail",[]{Rig t;PASS(t.j.begin());PASS(t.r.putNumber(Key(Kind::User,0,Field::Target),1));PASS(t.j.commit());PASS(t.j.begin());PASS(t.r.putNumber(Key(Kind::User,0,Field::Target),2));PASS(t.j.commit());uint32_t bad=40+get32(t.io.bytes.data()+20);t.io.bytes[bad+44]^=1;auto original=t.io.bytes;Journal recovered(t.io);REQUIRE(recovered.mount()==Status::Corrupt);REQUIRE(recovered.begin()!=Status::Ok);REQUIRE(t.io.bytes==original);});
    test("C07 W/C matches source material display",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.setField("cement","385"));PASS(t.app.setField("water","165"));PASS(t.app.dispatch("NAV","5"));Wire w;Transport p(t.app,w);w.input("CM1|0|0|5|0|PAGE_READY|2\n");drain(p);REQUIRE(w.tx.find("tWC.txt=\"0.43\"")!=std::string::npos);});
    test("C08 material metadata does not alter fit",[]{Rig t;t.baseline();Fit before,after;PASS(t.r.model(Kind::Draft,t.app.draftId(),before));PASS(t.app.setField("water","165"));PASS(t.app.generate());PASS(t.r.model(Kind::Draft,t.app.draftId(),after));REQUIRE(before.a==after.a&&before.b==after.b&&before.r2==after.r2);});
    test("C09 invalid target preserves committed value",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.setField("target","30"));REQUIRE(t.app.setField("target","")==Status::Missing);REQUIRE(t.app.setField("target","0")==Status::Invalid);REQUIRE(t.app.setField("target","-1")==Status::Invalid);Real target;PASS(t.r.number(Key(Kind::Draft,t.app.draftId(),Field::Target),target));REQUIRE(target==30);});
    test("C10 full day-zero slots cannot create duplicate half-hour",[]{Rig t;PASS(t.app.newBaseline());PASS(t.j.begin());for(uint32_t id=1;id<=48;++id){Row row;row.id=id;row.revision=1;row.timeH=Real(id-1)/2;PASS(t.r.putRow(Kind::Draft,t.app.draftId(),row));}PASS(t.r.putInteger(Key(Kind::Draft,t.app.draftId(),Field::MaxRow),48));PASS(t.j.commit());REQUIRE(t.app.addRow(true)==Status::Capacity);});
    test("C11 stale sensor command cannot fill another visible row",[]{Rig t;t.baseline();PASS(t.app.openBaseline(1));Wire w;Transport p(t.app,w);w.input("CM1|0|0|6|0|PAGE_READY|2\n");drain(p);std::string old=request(t,1,"ROW_SENSOR|0");PASS(t.app.addRow(true));for(unsigned i=0;i<3;++i)t.sensor.frame.channel[i]=99;w.input(old);drain(p);Row row;PASS(t.r.row(Kind::Draft,t.app.draftId(),1,row));REQUIRE(row.temp==20);});
    test("C12 editing generated rows prevents stale-model save",[]{Rig t;t.baseline();PASS(t.app.editRow(1,"temp","25"));REQUIRE(t.app.saveBaseline()==Status::Missing);uint32_t max;PASS(t.j.maxObject(Kind::Baseline,max));REQUIRE(max==1);});
    test("C13 active session survives panel reconnection",[]{Rig t;t.baseline();PASS(t.app.start());uint32_t session=t.app.sessionId();Wire w;Transport p(t.app,w);w.input("CM1|0|0|11|0|PAGE_READY|2\n");drain(p);std::ostringstream ready;ready<<"CM1|"<<t.app.bootToken()<<"|0|11|0|PAGE_READY|2\n";w.input(ready.str());drain(p);w.input("CM1|0|0|11|0|PAGE_READY|2\n");drain(p);uint32_t max;PASS(t.r.integer(Key(Kind::Session,session,Field::MaxRow),max));REQUIRE(t.app.sessionId()==session&&max==1);});
    test("C14 journal cannot write before mount",[]{host::MemoryStorage io;io.bytes.assign(100,42);auto before=io.bytes;Journal j(io);REQUIRE(j.begin()!=Status::Ok);REQUIRE(io.bytes==before);});

    test("A39 delayed ACK cannot clear a newer client request",[]{Rig t;Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);w.tx.clear();w.input(request(t,1,"FIELD_SET|operator|ACK_TEST"));drain(p);REQUIRE(w.tx.find("pInit.vBusy.val=0")==std::string::npos);REQUIRE(w.tx.find("pInit.vAckBoot.val=")!=std::string::npos);});
    test("A40 deleting selected baseline picks newest remaining baseline",[]{Rig t;t.baseline();PASS(t.app.saveBaseline());PASS(t.app.deleteBaseline(2,true));REQUIRE(t.app.selectedId()==1);Controller reboot(t.r,t.time,t.sensor,t.device);PASS(reboot.boot());REQUIRE(reboot.selectedId()==1);});
    test("A41 new lab row is focused and visible beyond first viewport",[]{Rig t;t.baseline();PASS(t.app.openBaseline(1));for(unsigned i=0;i<5;++i)PASS(t.app.addRow(false));uint32_t id=t.app.focusedRow();REQUIRE(id==8&&t.app.cursor()==6);Row row;PASS(t.app.rowAt(1,row));REQUIRE(row.id==id);});
    test("A42 day-zero edit preserves or allocates its half-hour slot",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(3,"day","1"));PASS(t.app.editRow(3,"day","0"));Row row;PASS(t.r.row(Kind::Draft,t.app.draftId(),3,row));REQUIRE(row.timeH==1);PASS(t.app.editRow(1,"timeH","2.5"));PASS(t.app.editRow(1,"day","0"));PASS(t.r.row(Kind::Draft,t.app.draftId(),1,row));REQUIRE(row.timeH==Real(2.5));});
    test("A43 cold boot follows explicit AutoSave false policy",[]{Rig t;REQUIRE(!t.app.settings().autoSave&&t.app.settings().intervalSeconds==300);});
    test("C15 shuffled stored rows integrate in chronological order",[]{Rig t;PASS(t.app.newBaseline());PASS(t.app.editRow(1,"day","2"));PASS(t.app.editRow(1,"timeH","2"));PASS(t.app.editRow(1,"temp","30"));PASS(t.app.editRow(2,"timeH","0"));PASS(t.app.editRow(2,"temp","10"));PASS(t.app.editRow(3,"day","1"));PASS(t.app.editRow(3,"timeH","1"));PASS(t.app.editRow(3,"temp","20"));StoredRows rows(t.r,Kind::Draft,t.app.draftId());Accumulator a;Row row;for(uint32_t id:{2u,3u,1u}){PASS(rows.next(row));REQUIRE(row.id==id);PASS(a.add(row.timeH,row.temp,0));}REQUIRE(rows.next(row)==Status::Missing&&a.maturity()==40);});
    test("C16 1.7 second loop stall uses actual sample delta",[]{Rig t;t.baseline();PASS(t.app.start());t.time.advance(1700);PASS(t.app.tick());REQUIRE(fabs(t.app.liveMaturity()-Real(40)*Real(1.7)/3600)<Real(.00000001));});
    test("C17 manual checkpoint edits replay and invalidate preview",[]{Rig t;t.baseline();PASS(t.app.start());t.time.advance(86400000);t.sensor.poll(t.time.value.monoMs);PASS(t.app.addCheckpoint(1));PASS(t.app.prepareResult());PASS(t.app.editCheckpoint(2,"temp","40"));Result result;REQUIRE(t.app.readResult(Kind::Session,1,result)==Status::Missing);PASS(t.app.checkpointResult(Kind::Session,1,0,result));REQUIRE(result.rawM==1200);PASS(t.app.editCheckpoint(1,"temp","30"));PASS(t.app.checkpointResult(Kind::Session,1,0,result));REQUIRE(result.rawM==1320&&result.initialTemp==30);char date[12],clock[12];PASS(calendarText(t.time.value.wallMs-3600000,date,sizeof(date),clock,sizeof(clock)));PASS(t.app.editCheckpoint(2,"date",date));PASS(t.app.editCheckpoint(2,"clock",clock));PASS(t.app.checkpointResult(Kind::Session,1,0,result));REQUIRE(result.rawM==1265);});
    test("A44 coalesced frames receive ordered responses",[]{Rig t;Wire w;Transport p(t.app,w);w.input("CM1|0|0|1|0|PAGE_READY|2\n");drain(p);w.tx.clear();w.input(request(t,1,"FIELD_SET|operator|FIRST")+request(t,2,"FIELD_SET|project|STALE_SECOND"));drain(p);size_t first=w.tx.find("pInit.vAck.val=1"),second=w.tx.find("pInit.vAck.val=2");REQUIRE(first!=std::string::npos&&second>first&&second!=std::string::npos);char text[65];REQUIRE(t.r.text(Key(Kind::User,0,Field::Project),text,65)==Status::Missing);});
    test("C18 native panel bytes cannot become an application command",[]{Parser parser;Frame frame;const uint8_t native[]={0x65,1,2,1,255,255,255,0x70,'C','M','1','|','1',255,255,255,'\n'};for(uint8_t byte:native)REQUIRE(parser.feed(byte,0,frame)!=Status::Ok);Status st=Status::Busy;for(unsigned char byte:std::string("CM1|1|2|1|1|USER_SAVE\n"))st=parser.feed(byte,1,frame);PASS(st);REQUIRE(frame.seq==2&&!strcmp(frame.verb,"USER_SAVE"));});
    test("C19 failed result SAVE preserves page and permits BACK and retry",[]{Rig t;t.baseline();PASS(t.app.start());PASS(t.app.prepareResult());t.io.full=true;REQUIRE(t.app.dispatch("RESULT_SAVE")==Status::Full);REQUIRE(t.app.page()==Page::Str&&t.app.historyId()==0);uint32_t id;REQUIRE(t.r.list(Kind::Result,0,id)==Status::Missing);PASS(t.app.dispatch("NAV","BACK"));REQUIRE(t.app.page()==Page::RT);t.io.full=false;PASS(t.app.dispatch("RESULT_PREPARE"));PASS(t.app.dispatch("RESULT_SAVE"));REQUIRE(t.app.historyId()==1&&t.app.page()==Page::Hist);});
    test("C20 active acquisition survives monotonic rollover",[]{Rig t;t.baseline();t.time.value.monoMs=UINT32_MAX-500;t.sensor.poll(t.time.value.monoMs);PASS(t.app.start());t.time.advance(1000);PASS(t.app.tick());REQUIRE(fabs(t.app.liveMaturity()-Real(40)/3600)<Real(.00000001));});
    test("C21 contradictory day and time order is rejected",[]{Rig t;t.baseline();PASS(t.app.editRow(2,"timeH","48"));PASS(t.app.editRow(3,"timeH","24"));REQUIRE(t.app.generate()==Status::Invalid);PASS(t.app.start());t.time.advance(86400000);t.sensor.poll(t.time.value.monoMs);PASS(t.app.addCheckpoint(2));t.time.advance(1000);t.sensor.poll(t.time.value.monoMs);REQUIRE(t.app.addCheckpoint(1)==Status::Invalid);uint32_t count;PASS(t.r.integer(Key(Kind::Session,1,Field::MaxRow),count));REQUIRE(count==2);});
    std::cout<<cases<<" cases, "<<failures<<" failed\n";return failures?1:0;
}
